// GUARDA DO CADASTRO: confere tudo de novo no servidor. O cargo nunca vem daqui.

// Freio por janela de tempo, guardado no estado do fluxo (por instância, só em produção).
function freio(nome, chave, limite, janelaMs) {
  const estado = $getWorkflowStaticData('global');
  estado[nome] = estado[nome] || {};
  const agora = Math.floor(Date.now() / janelaMs);
  for (const k of Object.keys(estado[nome])) {
    if (estado[nome][k].janela < agora) delete estado[nome][k];
  }
  const item = estado[nome][chave] && estado[nome][chave].janela === agora
    ? estado[nome][chave]
    : (estado[nome][chave] = { janela: agora, contador: 0 });
  item.contador++;
  if (item.contador > limite) throw new Error('429|MUITAS_TENTATIVAS|Muitas tentativas. Espere alguns minutos e tente de novo.');
}

// As mesmas regras do front (src/lib/validation.ts).
const normalizar = (v) => String(v || '').toUpperCase().replace(/[^0-9A-Z]/g, '');
function digitoCpf(digitos, peso) {
  let soma = 0;
  for (let i = 0; i < digitos.length; i++) soma += Number(digitos[i]) * (peso - i);
  const resto = soma % 11;
  return resto < 2 ? 0 : 11 - resto;
}
function cpfValido(d) {
  if (!/^\d{11}$/.test(d) || /^(\d)\1{10}$/.test(d)) return false;
  return digitoCpf(d.slice(0, 9), 10) === Number(d[9]) && digitoCpf(d.slice(0, 10), 11) === Number(d[10]);
}
function digitoCnpj(c) {
  let soma = 0, peso = 2;
  for (let i = c.length - 1; i >= 0; i--) { soma += (c.charCodeAt(i) - 48) * peso; peso = peso === 9 ? 2 : peso + 1; }
  const resto = soma % 11;
  return resto < 2 ? 0 : 11 - resto;
}
function cnpjValido(c) {
  if (!/^[0-9A-Z]{12}\d{2}$/.test(c) || /^(.)\1{13}$/.test(c)) return false;
  return digitoCnpj(c.slice(0, 12)) === Number(c[12]) && digitoCnpj(c.slice(0, 13)) === Number(c[13]);
}
const formatoDocumento = (d) => /^([0-9]{11}|[0-9A-Z]{12}[0-9]{2})$/.test(d);

freio('cadastroGlobal', 'todos', 20, 60000);

const b = $('Cadastro').first().json.body || {};
const falha = (msg) => { throw new Error('400|DADOS_INVALIDOS|' + msg); };
const texto = (v, max) => (typeof v === 'string' && v.trim().length <= max ? v.trim() : null);

if (b.docType !== 'cpf' && b.docType !== 'cnpj') falha('Tipo de documento inválido.');
const documento = normalizar(b.document);
if (b.docType === 'cpf' ? !cpfValido(documento) : !cnpjValido(documento)) falha('Documento inválido.');

const fullName = texto(b.fullName, 120);
if (!fullName) falha('Informe o nome completo.');
const socialName = texto(b.socialName || '', 120);
if (socialName === null) falha('Nome social inválido.');

const birthDate = typeof b.birthDate === 'string' ? b.birthDate : '';
if (!/^\d{4}-\d{2}-\d{2}$/.test(birthDate) || isNaN(Date.parse(birthDate)) || birthDate > new Date().toISOString().slice(0, 10)) {
  falha('Data de nascimento inválida.');
}

const phone = String(b.phone || '').replace(/\D/g, '');
if (!/^\d{10,11}$/.test(phone)) falha('Telefone inválido.');

const a = b.address || {};
const address = {
  cep: String(a.cep || '').replace(/\D/g, ''),
  street: texto(a.street, 120), number: texto(a.number, 8), complement: texto(a.complement || '', 60),
  district: texto(a.district, 120), city: texto(a.city, 120), state: String(a.state || ''),
};
if (!/^\d{8}$/.test(address.cep)) falha('CEP inválido.');
if (!address.street || !address.number || address.complement === null || !address.district || !address.city) falha('Endereço incompleto.');
if (!/^[A-Z]{2}$/.test(address.state)) falha('UF inválida.');

const senha = typeof b.password === 'string' ? b.password : '';
const ESPECIAIS = "!@#$%^&*()-_=+[]{};:'\",.<>/?|`~";
if (senha.length < 8 || senha.length > 128 || !/[A-ZÀ-ÖØ-Þ]/.test(senha) || !senha.split('').some((c) => ESPECIAIS.includes(c))) {
  falha('A senha precisa de pelo menos 8 caracteres, 1 letra maiúscula e 1 caractere especial.');
}

return [{ json: { dados: { docType: b.docType, document: documento, fullName, socialName, birthDate, phone, address }, senha } }];

const SIMULAR_SMS = true;
function pedido(r) {
  return {
    verificar: true,
